"""Generates flashcards/month-03.csv (Anki import: Front, Back, Tags) for Days 64-91. Edit the list, then re-run.
Every number on a card comes from a run of the course scripts on this box (CPU only). Days 61-63 are in month-02.csv.
Day 91 opens Month 4 and is tagged m4."""
import csv, os
C = [
(64,"What does loss.backward() compute?","Gradients of the scalar loss with respect to every tensor with requires_grad=True, accumulated into .grad."),
(64,"Why call optimizer.zero_grad() each step?","PyTorch accumulates gradients; without zeroing, each step uses the sum of all previous gradients."),
(64,"The five lines of a PyTorch training step?","zero_grad; forward (logits = model(x)); loss = loss_fn(logits, y); loss.backward(); optimizer.step()."),
(64,"What does torch.no_grad() do?","Disables graph recording, for evaluation and inference: less memory, faster."),
(64,"model.train() vs model.eval()?","Switches dropout and batch norm between training behaviour and inference behaviour; it does not disable gradients."),
(65,"What does a DataLoader add to a Dataset?","Batching, shuffling, optional parallel workers and collation into tensors."),
(65,"Why shuffle training data but not test data?","Shuffling decorrelates consecutive batches for SGD; evaluation order does not matter."),
(65,"Why pin_memory and non_blocking matter on GPUs?","Page-locked host memory allows asynchronous host-to-device copies that overlap with compute."),
(66,"Xavier/Glorot init variance?","Var(w) = 2/(fan_in + fan_out); keeps activation variance roughly constant for tanh-like layers."),
(66,"He/Kaiming init variance?","Var(w) = 2/fan_in; compensates for ReLU zeroing half the activations."),
(66,"Symptom of too-small initial weights in a deep net?","Activations and gradients shrink layer by layer (vanishing); early layers barely learn."),
(67,"Momentum update?","v ← βv + g; w ← w − ηv. Smooths noisy gradients and speeds up along consistent directions."),
(67,"What does Adam keep per parameter?","Moving averages of the gradient (m) and of its square (v), with bias correction; step ∝ m/√v."),
(67,"AdamW vs Adam with L2?","AdamW decouples weight decay from the adaptive step, applying it directly to the weights."),
(67,"What is a OneCycle schedule?","LR warms up to a maximum and then anneals to near zero within one training run."),
(68,"Inverted dropout at training time?","Zero each unit with probability p and scale survivors by 1/(1−p) so the expected activation is unchanged."),
(68,"Early stopping in one sentence?","Keep the checkpoint with the best validation score and stop after it has not improved for 'patience' epochs."),
(68,"Weight decay effect?","Shrinks weights towards zero each step, an L2 penalty that limits model complexity."),
(69,"What does batch norm normalise over in a CNN?","Each channel, over the batch and spatial dimensions; then applies learned scale γ and shift β."),
(69,"BN at inference uses?","Running averages of mean and variance collected during training (model.eval())."),
(69,"Layer norm normalises over?","The features of each example separately; independent of batch size, standard in transformers."),
(69,"Why drop conv bias before BN?","BN's shift β does the same job, so the bias is redundant."),
(70,"What belongs in an experiment log row?","Config (model, optimiser, LR, regularisation, seed), train and val metrics, time, and a note."),
(71,"Conv output size formula?","⌊(n + 2p − k)/s⌋ + 1."),
(71,"Conv2d(3, 16, 3) parameters?","448 = 16·3·3·3 + 16 (an equivalent dense layer for 3×32×32 → 16×30×30 would need 44,251,200)."),
(71,"What is im2col?","Copy each k×k×C patch into a column so the convolution becomes one matrix multiply."),
(71,"Loops vs im2col vs torch for the Day-71 conv?","About 213-244 ms, 2-3 ms and well under the loop time for torch (timings vary with load); same results to about 1e-14."),
(71,"Receptive field of three stacked 3×3 convs (stride 1)?","7 × 7."),
(71,"Do frameworks compute convolution or cross-correlation?","Cross-correlation (no kernel flip); they call it convolution."),
(72,"Why two 3×3 convs instead of one 5×5?","Same 5×5 receptive field, 18C² vs 25C² weights, and an extra non-linearity."),
(72,"Residual block formula?","y = F(x) + x (with a 1×1 strided projection on the skip when shapes change)."),
(72,"Day-72 plain vs residual at depth 10 (Fashion-MNIST, short training)?","Residual 0.7145 vs plain 0.6120 test accuracy; at depth 2 there was no gain."),
(72,"What is the degradation problem?","Deeper plain networks get higher training error: an optimisation failure, not overfitting."),
(72,"Global average pooling?","Average each final feature map to one number; tiny head, any input size."),
(73,"Day-73 CNN+BN vs MLP on CIFAR-10-small (10 epochs)?","Val accuracy 0.7444 vs 0.5020; the MLP had 1,578,506 parameters vs 308,394."),
(73,"Augmentations suitable for CIFAR-10?","Horizontal flip and random crop after 4-pixel padding; not vertical flips."),
(73,"Why did flip/crop not raise val accuracy in 10 epochs on Day 73?","It narrowed the train-val gap (0.19 → 0.07) but needs longer training to pay off."),
(74,"Three transfer-learning strategies?","Frozen features + linear model; fine-tune the top stage; fine-tune everything with small LRs."),
(74,"Day-74 results with 2,000 CIFAR images?","From scratch 0.3852, frozen ResNet-18 features + LR 0.6424, fine-tune layer4+fc 0.6856."),
(74,"Why must preprocessing match the pretrained weights?","The network expects inputs distributed as in its training (resize, ImageNet mean/std)."),
(75,"Expected initial cross-entropy for C balanced classes?","ln C (2.303 for 10 classes)."),
(75,"Overfit-one-batch test?","Train on ~32 examples; loss should approach 0. If not, the model/loss/optimiser is broken."),
(75,"Shuffled-label sanity check?","Train on permuted labels; test accuracy must fall to chance (0.0889 on Day 75). Higher means leakage."),
(75,"Symptom of softmax before cross_entropy?","Training still works but much worse (0.6497 vs 0.8381 test on Day 75)."),
(75,"Why is view wrong for NHWC → NCHW?","view reinterprets memory and mixes channels; use permute(0, 3, 1, 2)."),
(76,"STFT bin width and count for fs 8 kHz, n_fft 256?","31.25 Hz, 129 bins (n_fft/2 + 1)."),
(76,"Why log-magnitude spectrograms?","Compresses dynamic range; closer to perceived loudness; stabler CNN inputs."),
(76,"What is SpecAugment?","Masking random frequency bands and time spans of the spectrogram during training."),
(76,"Why did the time-averaged baseline fail on Day 76?","Averaging over time removes the difference between tones, beeps and chirps (0.7500 vs CNN 0.8775-0.8850)."),
(77,"Define expected calibration error (ECE).","Bin predictions by confidence; average |accuracy − confidence| over bins weighted by bin size."),
(77,"Day-77 Fashion-MNIST test accuracy and worst class?","0.8910 (cnn16); Shirt at 0.624."),
(77,"Share of Day-77 errors in the top 4 confused pairs?","0.58, all upper-body garments (T-shirt/Shirt 203, Coat/Shirt 153, ...)."),
(78,"Why is the gradient of W_h in an RNN a sum over time?","W_h is reused at every step; the total derivative adds all paths."),
(78,"BPTT backward step for the hidden state?","∂L/∂h_{t−1} = W_hᵀ (diag(1 − h_t²) ∂L/∂h_t) + direct terms."),
(78,"Day-78 |∂L/∂h_0| with W_h spectral radius 0.51 (T = 50)?","1.01e-19: the gradient vanished."),
(78,"Gradient clipping by norm?","If ||g|| > c, rescale g ← g · c/||g||."),
(78,"Truncated BPTT?","Backpropagate only k steps; carry the hidden state forward but detach it."),
(79,"LSTM cell update?","c_t = f ⊙ c_{t−1} + i ⊙ g; h_t = o ⊙ tanh(c_t)."),
(79,"∂c_t/∂c_{t−1} along the LSTM cell path?","f_t element-wise: no weight matrix, so gradients can survive many steps."),
(79,"Parameters of RNN / GRU / LSTM with I = 10, H = 32?","1,408 / 4,224 / 5,632 (gate multiples 1, 3, 4)."),
(79,"Effect of forget-gate bias 1 on Day 79?","LSTM at T = 20 rose from 0.7520 to 1.0; at T = 50 all models stayed near chance."),
(80,"SGNS loss for one pair and k negatives?","−log σ(u_c·v) − Σ_k log σ(−u_k·v)."),
(80,"Why subsample frequent words?","They create many low-information pairs that dominate training."),
(80,"What is anisotropy in embeddings, and the fix?","All vectors share a direction, inflating cosines; subtract the mean vector."),
(80,"Day-80 nearest neighbours of 'thou'?","wouldst, dost, livest, art, hast: a syntactic cluster from co-occurrence."),
(81,"The seq2seq bottleneck?","The whole input is squeezed into one fixed-size encoder state."),
(81,"Attention context vector?","Softmax of scores between decoder state and every encoder state, then the weighted sum of encoder states."),
(81,"Day-81 exact-match at length 16, without vs with attention?","0.000 vs 0.292."),
(81,"What is teacher forcing, and its side effect?","Feed true previous tokens in training; causes exposure bias at inference."),
(82,"fp16 vs bf16 layout?","fp16: 5 exponent, 10 mantissa (max 65,504); bf16: 8 exponent, 7 mantissa (fp32 range)."),
(82,"Why loss scaling for fp16?","Small gradients underflow: 1e-8 → 0 in fp16; scaled by 65,536 it survives and unscales to 9.997e-9."),
(82,"Why keep fp32 master weights?","Small updates would round to zero against larger weights in 16-bit."),
(82,"Day-82 profiler top op for the MNIST CNN on CPU?","mkldnn_convolution, about 22% of time; conv backward about 17%."),
(82,"What does .item() cost in a GPU loop?","A device synchronisation every call."),
(83,"jax.grad, jax.jit, jax.vmap?","Gradient function; trace-and-compile with XLA; vectorise over a batch axis."),
(83,"Why did a Python print run once in 3 jitted calls?","It runs only during tracing; later calls use compiled code."),
(83,"Day-83 first-call jit time vs per-call?","About 101 ms compile vs about 3-4 ms per jitted call (eager 8-10 ms)."),
(84,"Bits per character from loss in nats?","bits = nats / ln 2."),
(84,"Day-84 val bits/char: trigram vs GRU LM?","2.984 vs 2.159 after 1,500 steps (uniform 6.022)."),
(84,"Effect of sampling temperature?","Logits / τ: τ < 1 more conservative, τ > 1 more random."),
(84,"How to split text for LM validation?","By position (a contiguous held-out block), not random windows."),
(85,"Why random search beats grid search with few important hyperparameters?","Each trial tries a new value of every hyperparameter instead of repeating grid values."),
(85,"Search learning rate on which scale?","Log scale (e.g. 10^uniform(−3, −0.5))."),
(85,"Why measure seed noise before comparing configs?","Differences smaller than seed-to-seed variation are not evidence."),
(86,"First thing to report in a capstone?","Baselines (majority class, simple linear model) so the model's gain is measurable."),
(86,"What goes in a checkpoint?","Model state_dict plus config and normalisation statistics needed to reproduce predictions."),
(87,"What is an ablation?","Remove or change one component of the full system and measure the effect, all else fixed."),
(87,"Why use the same epochs and seed in ablations?","So differences come from the component, not the budget or the luck of the seed."),
(88,"Bias vs variance from train/val/test accuracy?","High train error = bias (underfit); large train-val gap = variance (overfit)."),
(88,"What is test-time augmentation (TTA)?","Average predictions over augmented copies (e.g. the flipped image) at inference."),
(88,"Abstention / selective prediction?","Refuse to predict below a confidence threshold; trade coverage for accuracy."),
(88,"Why tag a sample of errors by hand?","To estimate which error category is largest and worth fixing first."),
(89,"Params of a 784-128-10 MLP?","101,770."),
(89,"Gradient accumulation over k micro-batches?","Sum (or average) gradients over k backward passes, then one optimiser step: same as a k× larger batch."),
(90,"What must a model report contain?","Data and split, baselines, final metrics on test once, curves, ablations, error analysis, limitations."),
(91,"Scaled dot-product attention?","softmax(QKᵀ/√d_k) V."),
(91,"Why divide by √d_k?","q·k has std ≈ √d_k for unit-variance inputs (Day 91: 2.00/8.39/31.25 for d_k 4/64/1024); scaling restores ≈1."),
(91,"Causal mask?","Set scores for future positions to −inf before softmax so position t sees only ≤ t."),
(91,"Is self-attention without positions order-aware?","No, it is permutation-equivariant; positional encodings add order."),
(91,"Parameters of multi-head attention projections (no bias) with model width D?","4D² (Q, K, V and output projections); 1,024 for D = 16."),
]
p = os.path.join(os.path.dirname(__file__), "month-03.csv")
with open(p, "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    for d, q, a in C: w.writerow([q, a, f"{'m4' if d > 90 else 'm3'} d{d}"])
print(len(C), "cards ->", p)
